sections.syntax:
UPDATE table_name
SET column1 = value1, column2 = value2, ...
WHERE condition;

examples.code:
UPDATE Students
SET email = 'alice.new@example.com'
WHERE id = 1;

UPDATE Employees
SET salary = salary * 1.10
WHERE department = 'Sales';

UPDATE Products
SET price = price * 0.90
WHERE product_id IN (
  SELECT product_id FROM Promotions WHERE active = 1
);

DELETE FROM Orders
WHERE status = 'cancelled'
  AND order_date < '2024-01-01';

DELETE FROM Orders
WHERE customer_id IN (
  SELECT customer_id FROM Customers WHERE country = 'France'
);

-- WARNING: This deletes ALL rows!
DELETE FROM Students;

-- Always use WHERE:
DELETE FROM Students
WHERE id = 5;

-- DELETE (slow, row-by-row, can use WHERE):
DELETE FROM Students;

-- TRUNCATE (fast, all at once, no WHERE allowed):
TRUNCATE TABLE Students;
